const SPEC_KIT_COMMIT = '487af97864901462874f18f1c7f8d8adec0b7ddd';
const REPOSITORY_PATH = '/opt/dev-fabric/workspaces/spec-kit';
const FEATURE_SLUG = 'red-sdd-adapter';

function fail(message) {
  throw new Error('REQUEST_BUILD_FAILED: ' + message);
}

// Get current execution ID from n8n context
const executionId = $execution ? ($execution.id || 'unknown') : 'unknown';
if (!executionId || executionId === 'unknown') {
  fail('execution.id is unavailable — cannot bind run_id');
}

function createRunId() {
  const uuidSource =
    typeof globalThis.crypto?.randomUUID === 'function'
      ? globalThis.crypto.randomUUID()
      : Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12);
  // Format: red-sdd-<executionId>-<nonce>
  const combined = 'red-sdd-' + String(executionId) + '-' + uuidSource;
  const normalized = combined
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 64);

  if (!/^[a-z0-9][a-z0-9-]{2,63}$/.test(normalized)) {
    fail('run_id is outside the allowed pattern: ' + normalized);
  }

  return normalized;
}

if (!/^[a-z0-9][a-z0-9-]{2,62}$/.test(FEATURE_SLUG)) {
  fail('feature_slug is outside the allowed pattern');
}

return [
  {
    json: {
      schema_version: 1,
      action: 'prepare',
      taskstoissues: false,
      max_converge_loops: 1,
      spec_kit_commit: SPEC_KIT_COMMIT,
      run_id: createRunId(),
      project: {
        repository_path: REPOSITORY_PATH,
        feature_slug: FEATURE_SLUG
      }
    }
  }
];

const request = $input.first().json;

const EXPECTED_COMMIT = '487af97864901462874f18f1c7f8d8adec0b7ddd';
const ALLOWED_REPOSITORY_PATH = '/opt/dev-fabric/workspaces/spec-kit';
const ALLOWED_FEATURE_SLUG = 'red-sdd-adapter';
const ALLOWED_TOP_LEVEL = new Set([
  'schema_version',
  'action',
  'taskstoissues',
  'max_converge_loops',
  'spec_kit_commit',
  'run_id',
  'project'
]);
const ALLOWED_PROJECT_FIELDS = new Set(['repository_path', 'feature_slug']);
const CONTROL_FIELD_BLOCKLIST = [
  'prepare',
  'execute',
  'implement',
  'converge',
  'run',
  'deploy',
  'approval_request',
  'approval-request',
  'approvalRequest',
  'next_phase',
  'next-phase',
  'nextPhase'
];
const CONTROL_CHAR_PATTERN = /[\u0000-\u001f\u007f]/;
const SHELL_METACHAR_PATTERN = /[;&|$`()<>{}!#~*?\[\]\\'"]/;

function fail(code, message) {
  const error = new Error(code + ': ' + message);
  error.name = code;
  throw error;
}

function ensure(condition, code, message) {
  if (!condition) {
    fail(code, message);
  }
}

function ensurePlainObject(value, label) {
  ensure(!!value && typeof value === 'object' && !Array.isArray(value), 'REQUEST_VALIDATION_FAILED', label + ' must be an object');
}

function ensureExactKeys(value, allowed, label) {
  for (const key of Object.keys(value)) {
    ensure(allowed.has(key), 'REQUEST_VALIDATION_FAILED', label + ' contains unknown field: ' + key);
  }
}

function ensureSafeText(value, label) {
  ensure(typeof value === 'string', 'REQUEST_VALIDATION_FAILED', label + ' must be a string');
  ensure(!CONTROL_CHAR_PATTERN.test(value), 'REQUEST_VALIDATION_FAILED', label + ' contains control characters');
}

function stableStringify(value) {
  if (Array.isArray(value)) {
    return '[' + value.map((item) => stableStringify(item)).join(',') + ']';
  }

  if (value && typeof value === 'object') {
    const keys = Object.keys(value).sort();
    return '{' + keys.map((key) => JSON.stringify(key) + ':' + stableStringify(value[key])).join(',') + '}';
  }

  return JSON.stringify(value);
}

// =============================================================================
// Pure-JavaScript base64url encoder (NO Buffer dependency)
// Avoids n8n Buffer.from corruption observed in Execution 2493
// =============================================================================

const BASE64_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function base64urlEncode(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code < 0x80) {
      bytes.push(code);
    } else if (code < 0x800) {
      bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
    } else if (code < 0x10000) {
      bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    } else {
      bytes.push(0xf0 | (code >> 18), 0x80 | ((code >> 12) & 0x3f), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    }
  }

  let result = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b1 = bytes[i];
    const b2 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b3 = i + 2 < bytes.length ? bytes[i + 2] : 0;

    result += BASE64_CHARS[b1 >> 2];
    result += BASE64_CHARS[((b1 & 0x03) << 4) | (b2 >> 4)];
    result += i + 1 < bytes.length ? BASE64_CHARS[((b2 & 0x0f) << 2) | (b3 >> 6)] : '=';
    result += i + 2 < bytes.length ? BASE64_CHARS[b3 & 0x3f] : '=';
  }

  // Convert to base64url: + → -, / → _, strip =
  return result.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

function base64urlDecode(b64url) {
  // Convert base64url to standard base64
  let std = b64url.replace(/-/g, '+').replace(/_/g, '/');
  // Restore padding
  while (std.length % 4 !== 0) {
    std += '=';
  }

  const BASE64_LOOKUP = {};
  for (let i = 0; i < BASE64_CHARS.length; i++) {
    BASE64_LOOKUP[BASE64_CHARS[i]] = i;
  }

  const bytes = [];
  for (let i = 0; i < std.length; i += 4) {
    const b0 = BASE64_LOOKUP[std[i]] || 0;
    const b1 = BASE64_LOOKUP[std[i + 1]] || 0;
    const b2 = std[i + 2] === '=' ? 0 : (BASE64_LOOKUP[std[i + 2]] || 0);
    const b3 = std[i + 3] === '=' ? 0 : (BASE64_LOOKUP[std[i + 3]] || 0);

    bytes.push((b0 << 2) | (b1 >> 4));
    if (std[i + 2] !== '=') bytes.push(((b1 & 0x0f) << 4) | (b2 >> 2));
    if (std[i + 3] !== '=') bytes.push(((b2 & 0x03) << 6) | b3);
  }

  // Decode UTF-8 bytes to string
  let result = '';
  let i = 0;
  while (i < bytes.length) {
    const b0 = bytes[i++];
    if (b0 < 0x80) {
      result += String.fromCharCode(b0);
    } else if (b0 < 0xe0) {
      result += String.fromCharCode(((b0 & 0x1f) << 6) | (bytes[i++] & 0x3f));
    } else if (b0 < 0xf0) {
      result += String.fromCharCode(((b0 & 0x0f) << 12) | ((bytes[i++] & 0x3f) << 6) | (bytes[i++] & 0x3f));
    } else {
      result += String.fromCharCode(((b0 & 0x07) << 18) | ((bytes[i++] & 0x3f) << 12) | ((bytes[i++] & 0x3f) << 6) | (bytes[i++] & 0x3f));
    }
  }

  return result;
}

// =============================================================================
// Request validation
// =============================================================================

ensurePlainObject(request, 'request');

for (const key of CONTROL_FIELD_BLOCKLIST) {
  ensure(!(key in request), 'ACTION_CONFLICT_DETECTED', 'request contains unauthorized control field: ' + key);
}

ensureExactKeys(request, ALLOWED_TOP_LEVEL, 'request');
ensure(request.schema_version === 1, 'REQUEST_VALIDATION_FAILED', 'schema_version must equal 1');
ensure(request.action === 'prepare', 'ACTION_NOT_AUTHORIZED', 'action must equal prepare');
ensure(request.taskstoissues === false, 'REQUEST_VALIDATION_FAILED', 'taskstoissues must be false');
ensure(request.max_converge_loops === 1, 'REQUEST_VALIDATION_FAILED', 'max_converge_loops must equal 1');

ensureSafeText(request.spec_kit_commit, 'spec_kit_commit');
ensure(/^[a-f0-9]{40}$/.test(request.spec_kit_commit), 'REQUEST_VALIDATION_FAILED', 'spec_kit_commit must be a full SHA-1 hash');
ensure(request.spec_kit_commit === EXPECTED_COMMIT, 'REQUEST_VALIDATION_FAILED', 'spec_kit_commit does not match the pinned value');

ensureSafeText(request.run_id, 'run_id');
ensure(/^[a-z0-9][a-z0-9-]{2,63}$/.test(request.run_id), 'REQUEST_VALIDATION_FAILED', 'run_id is outside the allowed pattern');

ensurePlainObject(request.project, 'project');
ensureExactKeys(request.project, ALLOWED_PROJECT_FIELDS, 'project');

ensureSafeText(request.project.repository_path, 'project.repository_path');
ensure(!SHELL_METACHAR_PATTERN.test(request.project.repository_path), 'COMMAND_INJECTION_DETECTED', 'project.repository_path contains shell metacharacters');
ensure(request.project.repository_path === ALLOWED_REPOSITORY_PATH, 'REQUEST_VALIDATION_FAILED', 'project.repository_path is outside the allowlist');

ensureSafeText(request.project.feature_slug, 'project.feature_slug');
ensure(!SHELL_METACHAR_PATTERN.test(request.project.feature_slug), 'COMMAND_INJECTION_DETECTED', 'project.feature_slug contains shell metacharacters');
ensure(/^[a-z0-9][a-z0-9-]{2,62}$/.test(request.project.feature_slug), 'REQUEST_VALIDATION_FAILED', 'project.feature_slug is outside the allowed pattern');
ensure(request.project.feature_slug === ALLOWED_FEATURE_SLUG, 'REQUEST_VALIDATION_FAILED', 'project.feature_slug does not match the pinned value');

const normalizedRequest = {
  schema_version: 1,
  action: 'prepare',
  taskstoissues: false,
  max_converge_loops: 1,
  spec_kit_commit: EXPECTED_COMMIT,
  run_id: request.run_id,
  project: {
    repository_path: ALLOWED_REPOSITORY_PATH,
    feature_slug: ALLOWED_FEATURE_SLUG
  }
};

// =============================================================================
// Encoding with roundtrip verification (fixes Execution 2493 corruption)
// =============================================================================

const canonicalJson = stableStringify(normalizedRequest);

// Pure-JS base64url encode (no Buffer dependency)
const base64Payload = base64urlEncode(canonicalJson);

// Character set validation
ensure(/^[A-Za-z0-9_-]+$/.test(base64Payload), 'REQUEST_BASE64URL_CHARSET_INVALID', '_base64_payload contains invalid base64url characters');

// CRITICAL: Roundtrip verification — decode back and compare
// This catches any encoding corruption (e.g., n8n Buffer.from bugs)
const decodedBack = base64urlDecode(base64Payload);
ensure(decodedBack === canonicalJson, 'REQUEST_BASE64URL_ROUNDTRIP_FAILED', 'Base64-URL roundtrip verification failed — encoding is corrupted');

return [
  {
    json: {
      ...normalizedRequest,
      _canonical_json: canonicalJson,
      _base64_payload: base64Payload
    }
  }
];

const rawInput = $input.first().json;

// ADR-004 / Execution-2428 fix: n8n SSH node can output either:
//   Direct:    {"code": 66, "stdout": "", "stderr": "..."}
//   Nested:    {"json": {"code": 66, "stdout": "", "stderr": "..."}}
// Unwrap nested format, then extract code/stdout/stderr.
const sshResult =
  rawInput &&
  typeof rawInput === 'object' &&
  rawInput.json &&
  typeof rawInput.json === 'object' &&
  Object.prototype.hasOwnProperty.call(rawInput.json, 'code')
    ? rawInput.json
    : rawInput;

const request = $('Validate and Normalize Request').first().json;
const stdout = typeof sshResult.stdout === 'string' ? sshResult.stdout : '';
const stderr = typeof sshResult.stderr === 'string' ? sshResult.stderr : '';
const sshExitCode = Number.isInteger(sshResult.code) ? sshResult.code : null;
const ALLOWED_ADAPTER_STATUSES = new Set([
  'AMBER_REVIEW_APPROVAL_REQUIRED',
  'NEEDS_VALIDATION',
  'NEEDS_VALIDATION_ADAPTER_CONTRACT_CONFLICT',
  'RED_BLOCK'
]);
const EXECUTE_PHASE_PATTERN = /\b(execute|implement|converge|taskstoissues)\b/i;
const PROVIDER_AUTH_PATTERN = /\b(401|unauthorized|invalid[_ -]?api[_ -]?key|provider[_ -]?401)\b/i;
const APPROVAL_REQUEST_PATH_PATTERN = /^(?!.*\.\.)(?!.*[\u0000-\u001f\u007f]).*\/approval-request\.json$/;

// ADR-004: structured redacted error classes from adapter
const ADAPTER_ERROR_CLASS_PATTERN = /"error_class"\s*:\s*"(REQUEST_[A-Z_]+)"/;

// Execution binding: detect stale partial execution rejection
const PARTIAL_EXECUTION_PATTERN = /\bREQUEST_EXECUTION_BINDING_REJECTED\b/;

function buildResult(status, parsed, overrides = {}) {
  return [
    {
      json: {
        ok: overrides.ok ?? (status !== 'RED_BLOCK' && overrides.error_class == null),
        status,
        adapter_status: parsed && typeof parsed.adapter_status === 'string' ? parsed.adapter_status : null,
        run_id: request.run_id,
        action: 'prepare',
        runner_origin: parsed && parsed.runner_origin === 'CT102' ? 'CT102' : null,
        exit_code: Number.isInteger(parsed && parsed.adapter_exit_code)
          ? parsed.adapter_exit_code
          : (Number.isInteger(parsed && parsed.exit_code) ? parsed.exit_code : sshExitCode),
        profiles_completed: Array.isArray(parsed && parsed.profiles_completed) ? parsed.profiles_completed : [],
        approval_request_path:
          typeof (parsed && parsed.approval_request_path) === 'string' &&
          APPROVAL_REQUEST_PATH_PATTERN.test(parsed.approval_request_path)
            ? parsed.approval_request_path
            : null,
        error_class: overrides.error_class ?? null,
        safe_message: overrides.safe_message ?? null,
        stdout_length: stdout.length,
        stderr_length: stderr.length
      }
    }
  ];
}

function block(errorClass, safeMessage, parsed) {
  return buildResult('RED_BLOCK', parsed, { ok: false, error_class: errorClass, safe_message: safeMessage });
}

// ADR-004: Extract structured error class from stderr if adapter produced one
function extractErrorClassFromStderr() {
  const match = ADAPTER_ERROR_CLASS_PATTERN.exec(stderr);
  if (match) {
    return match[1];
  }
  // Also try parsing stderr as JSON for error_class key
  try {
    const errJson = JSON.parse(stderr);
    if (errJson && typeof errJson.error_class === 'string') {
      return errJson.error_class;
    }
  } catch (_) {
    // stderr not JSON, fall through
  }
  return null;
}

// =============================================================================
// Partial Execution Binding Rejection (Execution 2492 regression guard)
// =============================================================================
// Detects when adapter rejects due to stale execution-ID binding
// The adapter returns exit code 66 with REQUEST_EXECUTION_BINDING_REJECTED
if (sshExitCode === 66 && PARTIAL_EXECUTION_PATTERN.test(stderr)) {
  return buildResult('NEEDS_VALIDATION_PARTIAL_EXECUTION_REJECTED', null, {
    ok: false,
    error_class: 'REQUEST_EXECUTION_BINDING_REJECTED',
    safe_message: 'Adapter rejected request: execution-ID binding mismatch (stale partial execution)'
  });
}

// ADR-004: Exit code 66 is contract violation — map to precise error
if (sshExitCode === 66) {
  const extractedError = extractErrorClassFromStderr();
  const errorClass = extractedError || 'NEEDS_VALIDATION_ADAPTER_CONTRACT_CONFLICT';
  return buildResult('NEEDS_VALIDATION_ADAPTER_CONTRACT_CONFLICT', null, {
    ok: false,
    error_class: errorClass,
    safe_message: 'Adapter rejected request: exit code 66 (contract violation)'
  });
}

if (sshExitCode === null) {
  return block('RUNNER_RESPONSE_INVALID', 'SSH exit code is missing');
}

if (!stdout.trim()) {
  return block('RUNNER_RESPONSE_INVALID', 'Runner stdout is empty');
}

if (PROVIDER_AUTH_PATTERN.test(stdout) || PROVIDER_AUTH_PATTERN.test(stderr)) {
  return block('PROVIDER_AUTH_FAILURE', 'Provider authentication failure detected');
}

if (EXECUTE_PHASE_PATTERN.test(stdout) || EXECUTE_PHASE_PATTERN.test(stderr)) {
  return block('EXECUTE_ARTIFACT_DETECTED', 'Execute or converge artifact detected in SSH output');
}

let parsed;
try {
  parsed = JSON.parse(stdout);
} catch (error) {
  return block('RUNNER_RESPONSE_INVALID', 'Runner stdout is not valid JSON');
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return block('RUNNER_RESPONSE_INVALID', 'Runner response must be an object');
}

if ('action' in parsed && parsed.action !== 'prepare') {
  return block('ACTION_NOT_AUTHORIZED', 'Runner action is not prepare', parsed);
}

if ('runner_origin' in parsed && parsed.runner_origin !== 'CT102') {
  return block('RUNNER_ORIGIN_MISMATCH', 'Runner origin is not CT102', parsed);
}

if (
  'approval_request_path' in parsed &&
  parsed.approval_request_path !== null &&
  (
    typeof parsed.approval_request_path !== 'string' ||
    !APPROVAL_REQUEST_PATH_PATTERN.test(parsed.approval_request_path)
  )
) {
  return block('RUNNER_RESPONSE_INVALID', 'approval_request_path is not safe', parsed);
}

// ADR-004: adapter_exit_code is canonical (with fallback to exit_code for backward compat)
const effectiveExitCode = 'adapter_exit_code' in parsed
  ? parsed.adapter_exit_code
  : parsed.exit_code;

if (!Number.isInteger(effectiveExitCode)) {
  return block('RUNNER_RESPONSE_INVALID', 'Runner response has no valid adapter_exit_code or exit_code', parsed);
}

// ADR-004: adapter_exit_code != 0 must NEVER be treated as success
if (effectiveExitCode !== 0) {
  const errorClass = parsed.error_class || extractErrorClassFromStderr() || 'RUNNER_NONZERO_EXIT';
  return block(errorClass, 'Runner returned non-zero exit code: ' + effectiveExitCode, parsed);
}

// Check required fields after exit code validation
for (const field of ['schema_version', 'run_id', 'action', 'runner_origin', 'adapter_status', 'final_classification']) {
  if (!(field in parsed)) {
    return block('RUNNER_RESPONSE_INVALID', 'Runner response is missing required field: ' + field, parsed);
  }
}

if (parsed.run_id !== request.run_id) {
  return block('RUNNER_RESPONSE_INVALID', 'Runner run_id does not match request run_id', parsed);
}

if (!ALLOWED_ADAPTER_STATUSES.has(parsed.adapter_status)) {
  return block('RUNNER_RESPONSE_INVALID', 'Runner adapter_status is not allowlisted: ' + parsed.adapter_status, parsed);
}

const phaseSnapshot = JSON.stringify({
  status: parsed.adapter_status ?? parsed.status,
  phase: parsed.phase ?? null,
  next_phase: parsed.next_phase ?? null,
  next_step: parsed.next_step ?? null,
  final_classification: parsed.final_classification ?? null
});

if (EXECUTE_PHASE_PATTERN.test(phaseSnapshot)) {
  return block('EXECUTE_ARTIFACT_DETECTED', 'Execute or converge phase detected in runner response', parsed);
}

// Map adapter_status to normalized status
const effectiveStatus = parsed.adapter_status || parsed.status || 'RED_BLOCK';
const normalizedStatus =
  effectiveStatus === 'NEEDS_VALIDATION_ADAPTER_CONTRACT_CONFLICT'
    ? 'NEEDS_VALIDATION'
    : (ALLOWED_ADAPTER_STATUSES.has(effectiveStatus) ? effectiveStatus : 'RED_BLOCK');

return buildResult(normalizedStatus, parsed, {
  ok: normalizedStatus !== 'RED_BLOCK'
});

const input = $input.first().json;
const status = input.status;
const adapterExitCode = Number.isInteger(input.exit_code) ? input.exit_code : null;

// Allowlisted statuses including partial execution rejection
const isAllowedStatus =
  status === 'AMBER_REVIEW_APPROVAL_REQUIRED' ||
  status === 'NEEDS_VALIDATION' ||
  status === 'NEEDS_VALIDATION_ADAPTER_CONTRACT_CONFLICT' ||
  status === 'NEEDS_VALIDATION_PARTIAL_EXECUTION_REJECTED' ||
  status === 'RED_BLOCK' ||
  /^TOOL_GAP_[A-Z0-9_]+$/.test(status);

if (!isAllowedStatus) {
  throw new Error('FINAL_CLASSIFICATION_INVALID: unexpected status ' + String(status));
}

// ADR-004: adapter_exit_code != 0 must never produce AMBER_REVIEW_APPROVAL_REQUIRED
// If exit code is non-zero (including 66), force RED_BLOCK regardless of status
const effectiveClassification =
  adapterExitCode !== null && adapterExitCode !== 0
    ? 'RED_BLOCK'
    : status;

// Map NEEDS_VALIDATION_ADAPTER_CONTRACT_CONFLICT → RED_BLOCK
// Map NEEDS_VALIDATION_PARTIAL_EXECUTION_REJECTED → RED_BLOCK_PARTIAL_EXECUTION_REJECTED
let finalClassification;
if (effectiveClassification === 'NEEDS_VALIDATION_ADAPTER_CONTRACT_CONFLICT') {
  finalClassification = 'RED_BLOCK';
} else if (effectiveClassification === 'NEEDS_VALIDATION_PARTIAL_EXECUTION_REJECTED') {
  finalClassification = 'RED_BLOCK_PARTIAL_EXECUTION_REJECTED';
} else {
  finalClassification = effectiveClassification;
}

return [
  {
    json: {
      classification: finalClassification,
      run_id: input.run_id,
      action: 'prepare',
      runner_origin: input.runner_origin,
      exit_code: adapterExitCode,
      adapter_status: input.adapter_status ?? null,
      profiles_completed: Array.isArray(input.profiles_completed) ? input.profiles_completed : [],
      approval_request_path: input.approval_request_path ?? null,
      error_class: input.error_class ?? null,
      requires_human_review: finalClassification === 'AMBER_REVIEW_APPROVAL_REQUIRED',
      terminal: true
    }
  }
];
